["%s submits."] = "%s надсилає.",
["%s suddenly falls asleep."] = "%s раптово засинає.",
["%s summons a Blackhand Dreadweaver to his aid!"] = "%s викликає на допомогу «Ткача жаху Чорної руки»!",
["%s summons a Blackhand Veteran to his aid!"] = "%s викликає на допомогу ветерана «Чорної руки»!",
["%s summons a messenger..."] = "%s викликає посланця...",
["%s surveys the ground and nods approvingly."] = "%s оглядає місцевість і схвально киває головою.",
["%s swaggers heavily."] = "%s дуже самовпевнено вихиляється.",
["%s takes a big swig of ale."] = "%s робить великий ковток елю.",
["%s takes a more careful aim..."] = "%s прицілюється ще ретельніше...",
["%s takes aim again..."] = "%s знову наводить приціл...",
["%s takes aim at the bottles again..."] = "%s знову націлюється на пляшки...",
["%s takes aim at the bottles..."] = "%s наводить приціл на пляшки...",
